<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('customers.update');$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT * FROM customers WHERE id=:id');$st->execute([':id'=>$id]);$customer=$st->fetch();if(!$customer){flash('error','Customer not found.');redirect('customers/index');}$data=[];foreach(['name','phone','email','address','notes','credit_limit','status']as$k)$data[$k]=(string)($customer[$k]??'');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();foreach(array_keys($data)as$k)$data[$k]=trim((string)($_POST[$k]??''));if(mb_strlen($data['name'])<2)$errors['name']='Enter a customer name.';if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email.';try{$limit=money_to_cents($data['credit_limit']);if($limit<0)throw new InvalidArgumentException();}catch(Throwable){$errors['credit_limit']='Enter a valid credit limit.';$limit=0;}if(!$errors){$up=db()->prepare('UPDATE customers SET name=:name,phone=:phone,email=:email,address=:address,notes=:notes,credit_limit=:limit,status=:status WHERE id=:id');$up->execute([':name'=>$data['name'],':phone'=>$data['phone']?:null,':email'=>$data['email']?:null,':address'=>$data['address']?:null,':notes'=>$data['notes']?:null,':limit'=>cents_to_decimal($limit),':status'=>$data['status'],':id'=>$id]);audit_log('customer_updated','customers',$id,'Customer updated: '.$data['name'].'.');flash('success','Customer updated.');redirect('customers/view?id='.$id);}}
$pageTitle='Edit Customer';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><div class="page-toolbar"><div><a class="back-link" href="<?=e(app_url('customers/view?id='.$id))?>">← Customer</a><h2>Edit customer</h2></div></div><form method="post" class="form-card"><?=csrf_field()?><?php require __DIR__.'/_form.php';?><div class="form-actions"><a class="button button--ghost" href="<?=e(app_url('customers/view?id='.$id))?>">Cancel</a><button class="button button--primary">Save changes</button></div></form></main></div><?php require BASE_PATH.'/includes/footer.php';?>
